<?php
namespace App\Models;use App\Casts\DateOnly;use Illuminate\Database\Eloquent\Model;
/** Provides job cost snapshot behavior within the WorkIntel application. */ class JobCostSnapshot extends Model{public $timestamps=false;protected $fillable=['workspace_id','project_id','snapshot_date','currency','planned_labor','actual_labor','planned_expense','actual_expense','planned_procurement','actual_procurement','total_planned','total_actual','variance','generated_at'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['snapshot_date'=>DateOnly::class,'generated_at'=>'datetime','planned_labor'=>'decimal:2','actual_labor'=>'decimal:2','planned_expense'=>'decimal:2','actual_expense'=>'decimal:2','planned_procurement'=>'decimal:2','actual_procurement'=>'decimal:2','total_planned'=>'decimal:2','total_actual'=>'decimal:2','variance'=>'decimal:2'];}}
